   145|
   146|// ---------------------------------------------------------------------------
   147|// Naming helpers (pure)
   148|// ---------------------------------------------------------------------------
   149|
   150|function words(value: string): string[] {
   151|  return value
   152|    .replace(/[^a-zA-Z0-9]+/g, ' ')
   153|    .trim()
   154|    .split(/\s+/)
   155|    .filter(Boolean);
   156|}
   157|
   158|export function toPascalCase(value: string): string {
   159|  return words(value)
   160|    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
   161|    .join('') || 'Item';
   162|}
   163|
   164|export function toCamelCase(value: string): string {
