   168|
   169|export function toKebabCase(value: string): string {
   170|  const w = words(value);
   171|  return (w.length ? w.map((x) => x.toLowerCase()).join('-') : 'app');
   172|}
   173|
   174|export function toSnakeCase(value: string): string {
   175|  const w = words(value);
   176|  return (w.length ? w.map((x) => x.toLowerCase()).join('_') : 'item');
   177|}
   178|
   179|function pluralSnake(value: string): string {
   180|  const snake = toSnakeCase(value);
   181|  if (snake.endsWith('y')) return `${snake.slice(0, -1)}ies`;
