   192|export function validateAppSpec(spec: unknown): SpecValidation {
   193|  if (!spec || typeof spec !== 'object') {
   194|    return { ok: false, error: 'A spec object is required.' };
   195|  }
   196|  const candidate = spec as Partial<AppGeneratorSpec>;
