   201|    return { ok: false, error: `spec.kind must be one of: ${APP_GENERATOR_SUPPORTED_KINDS.join(', ')}.` };
   202|  }
   203|  const hasFeatures = Array.isArray(candidate.features) && candidate.features.some((f) => typeof f === 'string' && f.trim());
   204|  const hasEntities = Array.isArray(candidate.entities) && candidate.entities.length > 0;
   205|  if (!hasFeatures && !hasEntities) {
   206|    return { ok: false, error: 'spec must include at least one feature or one entity.' };
   207|  }
   208|  return { ok: true };
