   210|
   211|function normalizeEntities(entities: AppGeneratorEntity[] | undefined): AppGeneratorEntity[] {
   212|  const list = (entities ?? []).filter((e) => e && typeof e.name === 'string' && e.name.trim());
   213|  return list.map((entity) => {
   214|    const fields = (entity.fields ?? []).filter((f) => f && typeof f.name === 'string' && f.name.trim());
   215|    const hasId = fields.some((f) => f.name.toLowerCase() === 'id');
   216|    const normalized: AppGeneratorEntityField[] = hasId
