   236|  const entityNames = entities.map((e) => toPascalCase(e.name));
   237|  const isClient = kind === 'expo_app' || kind === 'web_app';
   238|  const layers: ArchitectureLayer[] = [];
   239|  if (isClient) {
   240|    layers.push({
   241|      name: 'Presentation',
   242|      responsibility: 'Screens, navigation, and reusable UI components.',
   243|      components: features.length ? features.map((f) => `${toPascalCase(f)}Screen`) : entityNames.map((n) => `${n}ListScreen`),
   244|    });
   245|    layers.push({
   246|      name: 'State',
   247|      responsibility: 'Typed context hooks + React Query for server state.',
   248|      components: entityNames.map((n) => `use${n}s`),
   249|    });
   250|  }
   251|  layers.push({
   252|    name: 'API',
   253|    responsibility: 'Owner-gated HTTP handlers that validate input and call services.',
   254|    components: entityNames.map((n) => `${n}Api`),
