   261|  layers.push({
   262|    name: 'Data',
   263|    responsibility: 'Persistence schema and migrations.',
   264|    components: entities.map((e) => pluralSnake(e.name)),
   265|  });
   266|  return {
   267|    pattern: isClient ? 'Layered MVVM (client) + service-oriented backend' : 'Service-oriented (API → service → store)',
   268|    layers,
   269|    dataFlow: [
   270|      isClient ? 'UI event → state hook → API call' : 'HTTP request → API handler',
   271|      'API handler validates input + auth',
   272|      'Service applies business rules',
   273|      'Store reads/writes persistence',
